// Deterministic Rule Engine Node
const geminiText = $input.first().json.candidates[0].content.parts[0].text;
const parsed = JSON.parse(geminiText);

// Recompute exact days between inception and admission
if (parsed.date_verification?.policy_start_date && parsed.medical_facts?.admission_date) {
  const start = new Date(parsed.date_verification.policy_start_date);
  const admission = new Date(parsed.medical_facts.admission_date);
  const diffDays = Math.floor((admission.getTime() - start.getTime()) / (1000 * 60 * 60 * 24));
  parsed.date_verification.active_policy_days = diffDays;
  parsed.date_verification.waiting_period_completed = diffDays >= (parsed.policy_analysis?.waiting_period_days || 730);
}

// Deterministic financial verification
parsed.claim.deducted_amount = Math.max(0, parsed.claim.claimed_amount - parsed.claim.approved_amount);
parsed.claim.disputed_amount = parsed.claim.deducted_amount;

return parsed;
